if GetLocale() ~= "ruRU" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.rogue.dps.Name"] = "Урон в ближнем бою"
L["rm.era.rogue.dps.Description"] = "Уровни 1–60, любая специализация, в том числе в игровых мирах «Хардкор» и Self-Found; составлено по симулятор, Icy Veins и Wowhead. Из незаметности: Умысел, Внезапный удар кинжалом, когда цель не смотрит на вас, Подлый трюк в одиночку, Гаррота вне рейдов. В бою: Ответный удар, Мясорубка от одного очка серии, если её нет на элитном противнике или цели с большим запасом здоровья (обновляется на пяти очках в последние три секунды), Ослабление доспеха на пяти очках в группе, если у вас Улучшенное ослабление доспеха 2/2 и никто не применяет Раскол брони, Потрошение на двух очках по цели, которая вот-вот умрёт, иначе Потрошение на пяти и никаких приёмов набора сверх пяти. Приём набора зависит от того, что вы знаете: Призрачный удар и Кровоизлияние вне рейдов, Удар в спину кинжалом, когда цель не смотрит на вас, иначе Коварный удар. Напоминания: яды на каждом оружии (Смертельный яд на оружии в левой руке, если оно есть), Пинок, Чай из чертополоха, Шквал клинков и Выброс адреналина против элитных противников или двух врагов при действующей Мясорубке, Хладнокровие на пяти очках, Ускользание в одиночной игре, когда вы ранены. Исчезновение, Парализующий удар, Подготовка, Удар по почкам и расовые способности есть в списке, но выключены; Ложный выпад, Спринт, Ослепление, Ошеломление и позиционирование остаются за вами."
L["rm.era.rogue.dps.simulator.Name"] = "Мечи, Коварный удар в такт ударам (симулятор)"
L["rm.era.rogue.dps.simulator.Description"] = "«Потный» порядок «Боя» по симулятор для Специализации на владении мечами — альтернатива рекомендуемой встроенной ротации «Урон в ближнем бою», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Коварный удар только сразу после удара правой рукой (до следующего 2,0 секунды или больше, настроено для меча со скоростью 2,6–2,8; измените это в копии), если только энергия не почти полна или цель не вот-вот умрёт, чтобы дополнительная атака мечом не задерживала ваш удар. Потрошение на пяти очках тоже ждёт Мясорубки, полной энергии или умирающей цели. В остальном — как рекомендуемая встроенная ротация."
L["rm.era.rogue.dps.warcrafttavern.Name"] = "Урон в ближнем бою, завершающие приёмы на пяти очках (Warcraft Tavern)"
L["rm.era.rogue.dps.warcrafttavern.Description"] = "Подход Warcraft Tavern — альтернатива рекомендуемой встроенной ротации «Урон в ближнем бою», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Каждый завершающий приём ждёт пяти очков серии, чтобы Неослабевающие удары возместили его. Мясорубка используется со второго ранга (42 уровень), когда её нет или она заканчивается, иначе Потрошение; без Мясорубки на малом числе очков, без Потрошения по умирающей цели и без Ослабления доспеха (его заменяет Раскол брони воина). Те же атаки из незаметности, приёмы набора и напоминания, что и в рекомендуемой встроенной ротации."
L["rm.forever.rogue.dps.Name"] = "Урон в ближнем бою"
L["rm.forever.rogue.dps.Description"] = "Урон в ближнем бою для любой специализации разбойника с 1 по 60 уровень, на основе Icy Veins, Wowhead и Warcraft Tavern. Приём набора очков зависит от того, что вы знаете: Расправа (Коварный удар для пятого очка), Кровоизлияние, Удар в спину, когда цель не смотрит на вас, иначе Коварный удар. Из незаметности начинает бой с Умысла, Подлого трюка в одиночку, Гарроты для «Скрытности» против элитных противников в группе, иначе с Внезапного удара или Гарроты. Поддерживает Мясорубку и «Яд», использует Ослабление доспеха в группах против элитных противников, если ни один воин не наложил пять Расколов брони, затем тратит пять очков на Рваную рану («Скрытность», долгие бои) или Потрошение и никогда не набирает больше пяти. Напоминания: яды на каждом оружии, Пинок, Шквал клинков и Выброс адреналина против групп и элитных противников, Хладнокровие, Ускользание, Ложный выпад, Чай из чертополоха и Подготовка. За вами остаются: Исчезновение, Спринт, Удар по почкам, Ослепление, Ошеломление и позиционирование. Forever ограничивает боевые данные, поэтому Rotation Master пока показывает эту встроенную ротацию только для справки и не выбирает её автоматически."
L["rm.forever.rogue.subtlety.warcrafttavern.Name"] = "Скрытность, билд с Внезапным ударом (Warcraft Tavern)"
L["rm.forever.rogue.subtlety.warcrafttavern.Description"] = "Билд «Скрытности» от Warcraft Tavern с Внезапным ударом и Горлорезом: Умысел и Внезапный удар в начале каждого боя, снова Внезапный удар всякий раз, когда это позволяет Горлорез, Удар в спину из-за спины как приём набора очков (Кровоизлияние, когда цель смотрит на вас), Призрачный удар по готовности, а на пяти очках — Мясорубка, затем Потрошение, без Рваной раны. Напоминает об Исчезновении ради ещё одного Внезапного удара по боссу, которого держит танк. Выбирайте её вместо рекомендуемой встроенной ротации разбойника, если вы взяли таланты Горлореза; она применяется, когда «Скрытность» — ваша основная ветка талантов и выбран Горлорез. Те же напоминания о ядах и способностях с восстановлением, что и в рекомендуемой встроенной ротации. Альтернатива рекомендуемой встроенной ротации разбойника «Урон», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.forever.rogue.subtlety.wowhead.Name"] = "Скрытность, билд с Гарротой (Wowhead)"
L["rm.forever.rogue.subtlety.wowhead.Description"] = "«Скрытность» по Wowhead: Умысел и Гаррота в начале каждого боя, а Исчезновение (затем Подготовка) используется в ротации, чтобы снова начать с Гарроты, когда предыдущая истекла. Мясорубка поддерживается, Ослабление доспеха — в группах, Рваная рана — добивающий приём на пяти очках, Кровоизлияние — единственный приём набора очков. Так Исчезновение, ваш способ спастись, тратится на урон: выбирайте этот вариант осознанно. Применяется, когда «Скрытность» — ваша основная ветка талантов, выбраны «Грязные трюки» и известен Умысел. Те же напоминания о ядах и способностях с восстановлением, что и в рекомендуемой встроенной ротации. Альтернатива рекомендуемой встроенной ротации разбойника «Урон», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.mop.rogue.assassination.Name"] = "Рекомендуемая"
L["rm.mop.rogue.assassination.Description"] = "Рекомендуется для «Ликвидации» с 10 по 90 уровень (симулятор и Wowhead для 5-й фазы, с шагами прокачки от Icy Veins). Начинает бой из незаметности Подлым трюком в одиночку, иначе Расправой (Устранение при Слепой зоне, с кинжалом). Поддерживает Мясорубку (с 60 уровня её обновляет Отравление) и Рваную рану на цели, тратит пять очков на Отравление, пока действует Рваная рана, и четыре очка, чтобы не прерывать положительный эффект Отравления, если у вас нет Предчувствия, затем Метка смерти, Устранение ниже 35% или при Слепой зоне (нужен кинжал в правой руке) и Расправа. Против четырёх и более врагов, сражающихся с вами: Мясорубка, Кровавый вихрь при семи, Рваная рана, Отравление и Веер клинков; перенос Рваной раны на другие цели — за вами. В одиночной игре добавляет Заживление ран и Удар по почкам при низком здоровье. Напоминания: яды, Пинок, Вендетта в долгих боях, Теневые клинки вместе с Вендеттой, Исчезновение и Подготовка во время Вендетты, Шаг сквозь тень с дистанции, Ускользание в одиночной игре. За вами остаются: Маленькие хитрости и Ослабление доспеха (есть в списке, но выключены), Уловка, Спринт и позиционирование."
L["rm.mop.rogue.assassination.icyveins.Name"] = "Отравление на пяти очках (Icy Veins)"
L["rm.mop.rogue.assassination.icyveins.Description"] = "По умолчанию выключена. Порядок Icy Veins и Method: Исчезновение по готовности ради Расправы из незаметности, Вендетта по готовности, если бой достаточно долгий, Отравление только на пяти очках, Рваная рана постоянно поддерживается, Устранение ниже 35% или при Слепой зоне, Расправа. От четырёх до восьми врагов: Веер клинков с Рваной раной на трёх и более очках; девять и более: только Веер клинков и Отравление. Рекомендуемая встроенная ротация «Ликвидация» следует более новым советам 5-й фазы; чтобы использовать эту, включите её и выключите рекомендуемую."
L["rm.mop.rogue.combat.Name"] = "Рекомендуемая"
L["rm.mop.rogue.combat.Description"] = "Рекомендуется для «Боя» с 10 по 90 уровень (Wowhead и симулятор для 5-й фазы). С патча «Осада Оргриммара» Коварный удар стоит 50 энергии, поэтому приём набора — Пробивающий удар, а Коварный удар используется только под Жаждой крови или Героизмом вместе с Выбросом адреналина (и до 20 уровня). Начинает бой Подлым трюком в одиночку, иначе Внезапным ударом. Поддерживает Мясорубку от двух очков и Пробивающий удар на цели, тратит пять очков только пока действует Пробивающий удар (Мясорубка, Рваная рана в долгом бою против одной цели без Шквала клинков, Потрошение) и на пяти очках ждёт энергию. Против восьми и более врагов: Мясорубка, Кровавый вихрь и Веер клинков. В одиночной игре добавляет Заживление ран и Удар по почкам. Напоминания: яды, Пинок, включение Шквала клинков против двух и более врагов и его выключение, Выброс адреналина при малом запасе энергии вместе с Теневыми клинками, Череда убийств, Исчезновение и Подготовка ради Внезапного удара при Глубоком понимании, Шаг сквозь тень, Ускользание в одиночной игре. За вами остаются: Маленькие хитрости и Ослабление доспеха (есть в списке, но выключены), Уловка и позиционирование за спиной цели для Внезапного удара."
L["rm.mop.rogue.combat.hekili.Name"] = "Предчувствие (Hekili)"
L["rm.mop.rogue.combat.hekili.Description"] = "По умолчанию выключена. Порядок Hekili для «Боя» с Предчувствием в MoP: Пробивающий удар — единственный приём набора, даже под Жаждой крови; завершающие приёмы ждут Глубокого понимания, четырёх зарядов Предчувствия или скорой готовности Теневых клинков, затем Мясорубка, Рваная рана на одной или двух долгоживущих целях, Кровавый вихрь против семи врагов и Потрошение; Мясорубка досрочно обновляется при 11 наложениях Коварства бандита; Веер клинков от четырёх врагов. Применима только с талантом Предчувствие. Чтобы использовать её, включите её и выключите рекомендуемую встроенную ротацию «Бой»."
L["rm.mop.rogue.combat.icyveins.Name"] = "Набор Коварным ударом (Icy Veins)"
L["rm.mop.rogue.combat.icyveins.Description"] = "По умолчанию выключена и для 5-й фазы устарела. Порядок Icy Veins, Warcraft Tavern, Method и wowtbc.gg времён до патча «Осада Оргриммара»: Мясорубка, Пробивающий удар постоянно поддерживается, Рваная рана на пяти очках в долгом бою против одной цели и Потрошение, с Коварным ударом как приёмом набора. Те же напоминания и игра против групп, что и в рекомендуемой встроенной ротации «Бой». Выбирайте её, только если следуете этим руководствам; включите её и выключите рекомендуемую."
L["rm.mop.rogue.subtlety.Name"] = "Рекомендуемая"
L["rm.mop.rogue.subtlety.Description"] = "Рекомендуется для «Скрытности» с Теневой концентрацией с 10 по 90 уровень (симулятор и Wowhead для 5-й фазы). В незаметности или Танце теней: Умысел, Мясорубка перед боем, завершающие приёмы на пяти очках, Внезапный удар, Гаррота. Вне их: Мясорубка; на пяти очках — Мясорубка и Рваная рана, когда они вот-вот спадут, Потрошение, пока действуют обе; Метка смерти; Кровоизлияние для поддержания его кровотечения; Удар в спину (с кинжалом), когда цель не атакует вас, иначе Кровоизлияние. Против трёх и более врагов: Мясорубка, Кровавый вихрь, Потрошение и Веер клинков. В одиночной игре добавляет Заживление ран и Удар по почкам. Напоминания: яды, Пинок, Танец теней при 75 энергии с действующими Мясорубкой и Рваной раной, Исчезновение, когда заканчивается Поиск слабости, Подготовка, Теневые клинки вне Танца и незаметности, Шаг сквозь тень, Ускользание в одиночной игре. За вами остаются: позиция за спиной цели (RM не видит, куда она обращена), Маленькие хитрости и Ослабление доспеха (есть в списке, но выключены)."
L["rm.mop.rogue.subtlety.warcrafttavern.Name"] = "Увертка (Warcraft Tavern)"
L["rm.mop.rogue.subtlety.warcrafttavern.Description"] = "Выбирается автоматически вместо встроенной ротации с Теневой концентрацией, когда ваш талант 1-го ряда — Увертка (билд Warcraft Tavern). Умысел и Мясорубка перед боем; в незаметности, Танце теней или в остаточном действии Увертки — завершающие приёмы на пяти очках, а затем Внезапный удар так часто, как он проходит. Два или три врага: поддерживать Рваную рану и тратить пять очков на Кровавый вихрь вместо Потрошения; от четырёх добавляется Веер клинков. Одна цель: Мясорубка, Рваная рана, Потрошение, Кровоизлияние ради его кровотечения, Удар в спину из-за спины с кинжалом, иначе Кровоизлияние. Танец теней и Исчезновение — напоминания при 60 энергии с действующей Мясорубкой; подгонять их под срабатывания аксессуаров, как советует Tavern, — за вами."
L["rm.mop.rogue.unspecialized.Name"] = "Без специализации"
L["rm.mop.rogue.unspecialized.Description"] = "Для уровней 1–9 или разбойника, который ещё не выбрал специализацию; встроенная ротация каждой специализации вступает в силу, как только вы её выберете. Начинает бой из незаметности Подлым трюком в одиночку, Внезапным ударом или Коварным ударом; предлагает Незаметность вне боя; Мясорубка от двух очков, Заживление ран и Удар по почкам в одиночной игре при ранении, Потрошение на четырёх очках (на двух, когда цель вот-вот умрёт), Коварный удар. Напоминания: яды, как только изучены, Пинок, Ускользание в одиночной игре."
L["rm.retail.rogue.assassination.Name"] = "Боевой помощник Blizzard"
L["rm.retail.rogue.assassination.Description"] = "Рекомендуется для специализации «Ликвидация» в Midnight. В бою игра теперь скрывает от аддонов ваши кровотечения, положительные эффекты, энергию, время восстановления и здоровье, поэтому эта ротация показывает собственное предложение Боевого помощника Blizzard (ротация одной кнопкой, которая берёт на себя начало боя из незаметности, Гарроту, Рваную рану, Отравление, Знак смерти и Погибель королей) и приостанавливается, пока вы применяете заклинание или у вас нет враждебной цели. Напоминания о том, что оно упускает: смертельный и несмертельный яды и Незаметность между боями, Исчезновение, когда вы в бою вне незаметности, Пинок против прерываемого заклинания (он загорается только там, где игра позволяет прочитать заклинание). Здоровье на Retail скрыто, поэтому Алый фиал — на ваше усмотрение."
L["rm.retail.rogue.assassination.icyveins.Name"] = "Для справки (Icy Veins)"
L["rm.retail.rogue.assassination.icyveins.Description"] = "Только для справки, по умолчанию выключена: порядок Icy Veins и SimulationCraft поддерживает кровотечения по их таймерам, которые Midnight скрывает в бою; энергия на Retail скрыта, поэтому накопление энергии опущено. Из незаметности — Гаррота, затем Внезапный удар. Гаррота в последние 30% длительности, пока очки серии не полны, Рваная рана при 5+ очках в последние 30% длительности; при 5+ очках серии — Удар милосердия или Отравление; при меньшем числе — Кровавый вихрь против трёх и более врагов, Веер клинков против двух и более рядом, Внезапный удар, Расправа. Напоминания: Знак смерти при обоих кровотечениях, Погибель королей вместе с ним, Исчезновение при готовом Знаке смерти, Отравляющий укол по цели с Меткой ловчего смерти, Чай из чертополоха по готовности в бою, а также общие напоминания о ядах, Незаметности и Пинке."
L["rm.retail.rogue.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.rogue.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию разбойника). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций разбойника, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.retail.rogue.outlaw.Name"] = "Боевой помощник Blizzard"
L["rm.retail.rogue.outlaw.Description"] = "Рекомендуется для специализации «Головорез» в Midnight. Показывает предложение Боевого помощника Blizzard (оно берёт на себя начало боя из незаметности, Бросок костей, Шквал клинков, Выброс адреналина, Промеж глаз и добивающие приёмы) и приостанавливается, пока вы применяете заклинание или у вас нет враждебной цели. Напоминания о том, что оно упускает: яды и Незаметность между боями, Исчезновение, когда вы в бою вне незаметности, Пинок. Здоровье на Retail скрыто, поэтому Алый фиал — на ваше усмотрение. Призовая игра остаётся за вами: игра скрывает, сколько у вас положительных эффектов Броска костей."
L["rm.retail.rogue.outlaw.icyveins.Name"] = "Для справки (Icy Veins)"
L["rm.retail.rogue.outlaw.icyveins.Description"] = "Только для справки, по умолчанию выключена: порядок Icy Veins, SimulationCraft и Wowhead читает положительные эффекты Броска костей, наложения Замечательной возможности и энергию, которые Midnight скрывает в бою. Из незаметности — Внезапный удар. Когда до полных очков серии не хватает одного или очки полны: Промеж глаз, Череда убийств, Удар милосердия, Устранение. Иначе Внезапный удар с Дерзостью, Выстрел из пистоли при шести наложениях Замечательной возможности (трёх при нехватке очков серии), Внезапный удар, Коварный удар. Напоминания: Бросок костей, когда не действует ни один его эффект, Выброс адреналина при двух очках серии или меньше, Шквал клинков поддерживается против двух и более врагов, Натиск клинка, Подготовка, когда Выброс адреналина, Промеж глаз и Натиск клинка восстанавливаются. Призовая игра остаётся ручной."
L["rm.retail.rogue.subtlety.Name"] = "Боевой помощник Blizzard"
L["rm.retail.rogue.subtlety.Description"] = "Рекомендуется для специализации «Скрытность» в Midnight. Показывает предложение Боевого помощника Blizzard (оно берёт на себя начало боя из незаметности, Теневые клинки, Укус Кровавой Пасти, Танец теней, Тайный прием и добивающие приёмы) и приостанавливается, пока вы применяете заклинание или у вас нет враждебной цели. Напоминания о том, что оно упускает: яды и Незаметность между боями, Пинок против прерываемого заклинания. Здоровье на Retail скрыто, поэтому Алый фиал — на ваше усмотрение."
L["rm.retail.rogue.subtlety.icyveins.Name"] = "Для справки (Icy Veins)"
L["rm.retail.rogue.subtlety.icyveins.Description"] = "Только для справки, по умолчанию выключена: порядок Icy Veins и SimulationCraft придерживает Танец теней для Тайного приема и читает Танец теней, Непроглядную ночь и энергию, которые Midnight скрывает в бою. В незаметности перед боем: Удар Тьмы. Когда до полных очков серии не хватает одного или очки полны: Потрошение с Непроглядной ночью, Тайный прием во время Танца теней, Удар милосердия, Черный порох против трёх и более врагов, Потрошение. Иначе Удар Тьмы, Шквал сюрикэнов против двух и более, Клинок мрака или Удар в спину. Напоминания: Укус Кровавой Пасти во время Танца теней, Теневые клинки при готовом Танце теней, Танец теней при двух очках серии или меньше (или шести и более), когда готов Тайный прием или действуют Теневые клинки, Исчезновение вне незаметности при двух очках серии или меньше."
L["rm.sod.rogue.dps.Name"] = "Урон в ближнем бою (SoD)"
L["rm.sod.rogue.dps.Description"] = "Сезон открытий, уровни 1–60, руны используются по мере того, как вы их гравируете; составлено по симулятор (6-я фаза), Icy Veins и Zockify (8-я фаза). Из незаметности: Теневой удар, Гаррота в группе, Внезапный удар для билда с Ударом в спину и кинжалом, Подлый трюк в одиночку. Против трёх и более врагов, сражающихся с вами, сначала Мушкетон, Кровавый вихрь, Веер клинков. Затем Внезапный удар при срабатывании Горлореза (с кинжалом), Удар саблей поддерживается на трёх наложениях, Отравленный нож при четырёх наложениях яда, Мясорубка от двух очков (обновляется от четырёх, если не выгравировано «Прямо к делу»), Ослабление доспеха, если никто не применяет Раскол брони и не поддерживает Подкожный яд, с выгравированной Резнёй — кровотечение (Кровавый вихрь, иначе Рваная рана; ни того, ни другого с Ударом саблей), Отравление на пяти очках (Потрошение, пока вы его не выгравировали) и приём набора по руне на перчатках: Расправа, Удар саблей, Удар в спину (с кинжалом), иначе Коварный удар. Напоминания: временные чары на каждом оружии, Пинок, Чай из чертополоха, Шквал клинков, Выброс адреналина, Хладнокровие и Ускользание, а с выгравированным Мастером скрытности — Исчезновение для его обновления и Подготовка."
L["rm.sod.rogue.dps.icyveins.Name"] = "Урон в ближнем бою, Рваная рана для Резни (SoD, Icy Veins)"
L["rm.sod.rogue.dps.icyveins.Description"] = "Порядок Icy Veins для сезона открытий — альтернатива рекомендуемой встроенной ротации «Урон в ближнем бою» для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Каждый завершающий приём на пяти очках серии, сначала Мясорубка, когда её нет или она заканчивается, затем Рваная рана, поддерживаемая, когда выгравирована Резня, затем Отравление; Отравленный нож только при пяти наложениях яда; Мушкетон или Веер клинков против трёх врагов. Те же атаки из незаметности, приёмы набора и напоминания, что и в рекомендуемой встроенной ротации; поддержание Подкожного яда остаётся за вами."
L["rm.sod.rogue.dps.zockify.Name"] = "Урон в ближнем бою, упрощённое Отравление (SoD, Zockify)"
L["rm.sod.rogue.dps.zockify.Description"] = "Упрощённый список Zockify для сезона открытий — альтернатива рекомендуемой встроенной ротации «Урон в ближнем бою» для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Без кровотечений и без Ослабления доспеха. Отравленный нож при четырёх наложениях яда, Мясорубка, когда её нет (от двух очков, от четырёх с Ударом саблей), Отравление на пяти очках, затем приём набора по руне на перчатках. Всплеск урона с Исчезновением и Хладнокровием остаётся за вами."
L["rm.sod.rogue.tank.Name"] = "Танк (SoD)"
L["rm.sod.rogue.tank.Description"] = "Танк для сезона открытий; выбирается, когда выгравирована «Просто царапина»; составлено по симулятор (6-я фаза), Icy Veins, Zockify и Warcraft Tavern. Ответный удар, Главный аргумент по готовности, Танец клинков от одного очка серии (обновляется от трёх), Мясорубка от трёх (обновляется от четырёх), Веер клинков, Кровавый вихрь и Мушкетон против трёх и более врагов, Мушкетон, пока действует Танец клинков, Потрошение на пяти очках при обоих положительных эффектах, Отравленный нож при малом запасе энергии, затем Удар саблей, Расправа или Коварный удар. Напоминания: Издевка в группе, когда ваша цель атакует кого-то другого, Пинок, Ускользание при здоровье ниже половины, Шквал клинков, Выброс адреналина, Чай из чертополоха и яды на оружии (на левой руке — только с оружием в левой руке). Шаг сквозь тень и поддержание Подкожного яда остаются за вами."
L["rm.tbc.rogue.dps.simulator.Name"] = "Урон в ближнем бою (симулятор)"
L["rm.tbc.rogue.dps.simulator.Description"] = "Уровни 1–70, любая ветка талантов. Из незаметности: Умысел, затем Подлый трюк в одиночку или Гаррота в группе, иначе Внезапный удар (с кинжалом в основной руке). В бою: Ответный удар, Мясорубка от двух очков серии (обновляется в последние две секунды), Потрошение по цели, которая вот-вот умрёт, а на пяти очках — Рваная рана, если она успеет отработать (но не во время Шквала клинков), иначе Потрошение. Набирает очки Расправой или Ударом в спину (кинжал), когда цель не атакует вас, иначе Кровоизлиянием или Коварным ударом. Напоминает об отсутствующих ядах, Пинке, Шквале клинков и Выбросе адреналина, Хладнокровии и Ускользании. Ослабление доспеха, Удар по почкам, Ложный выпад, Исчезновение и позиционирование остаются за вами."
L["rm.tbc.rogue.dps.wowhead.Name"] = "Урон в ближнем бою (Wowhead)"
L["rm.tbc.rogue.dps.wowhead.Description"] = "Уровни 1–70, любая ветка талантов, по Wowhead. Те же атаки из незаметности, приёмы набора очков и напоминания, что и в версии симулятор, но Мясорубка ставится уже с одного очка серии, а каждый добивающий приём на пяти очках — Потрошение: без Рваной раны. Ослабление доспеха, Удар по почкам, Ложный выпад, Исчезновение и позиционирование остаются за вами. Альтернатива рекомендуемой встроенной ротации «Урон в ближнем бою» (симулятор), отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
